use std::fs

fn digit_val(c: char) -> int {
    let d = c as int
    if d >= 48 && d <= 57 {
        d - 48
    } else if d >= 65 && d <= 90 {
        d - 55
    } else {
        d - 87
    }
}

fn digit_char(v: int) -> string {
    let c = if v < 10 { 48 + v } else { 55 + v }
    let ch: char = (c as u8) as char
    "${ch}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out = ""
        while n > 0 {
            out = digit_char(n % to) + out
            n = n / to
        }
        println(out)
    }
}

